<?php $display=static fn($value)=>trim((string)($value??''))!==''?(string)$value:'Not recorded'; ?>
<div class="executive-people ep-profile <?= $member?'is-member':'is-voter' ?>"><a class="ep-back" href="<?= e(url($back)) ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i>Back to <?= $member?'members':'voters' ?></a><header class="ep-profile-heading"><div><span class="section-kicker"><?= $member?'MEMBERSHIP PROFILE':'VOTER RECORD' ?> · MY JURISDICTION</span><h1><?= e($person['full_name']) ?></h1><div class="d-flex flex-wrap align-items-center gap-2"><?php if($member): ?><?= badge($person['membership_status']) ?><?php else: ?><span class="badge bg-light text-dark">Not a member</span><?php endif; ?><?php if($person['is_deceased']): ?><span class="badge bg-secondary">Deceased</span><?php endif; ?><span class="small text-secondary">Voter ID: <?= e($person['voter_id']) ?></span></div></div><?php if($canEdit): ?><a class="btn btn-primary no-print" href="<?= e(url('branch_voter_edit',['id'=>$person['id']])) ?>"><i class="bi bi-pencil-square me-2" aria-hidden="true"></i>Update contact details</a><?php endif; ?></header>
<div class="ep-profile-grid"><aside><section class="card card-body ep-identity"><?php if($person['has_photo']): ?><img class="ep-portrait" src="<?= e(url('voter_photo',['id'=>$person['id']])) ?>" alt="Photo of <?= e($person['full_name']) ?>"><?php else: ?><div class="ep-portrait ep-placeholder" aria-label="No photo"><?= e(mb_strtoupper(mb_substr($person['full_name'],0,1))) ?></div><?php endif; ?><h2 class="h6 mt-3 mb-1"><?= e($person['full_name']) ?></h2><p class="small text-secondary"><?= e(label($person['gender'])) ?></p><?php if($member): ?><span class="section-kicker"><?= trim((string)$person['official_membership_id'])!==''?'PARTY ID':'SYS NO.' ?></span><strong class="ep-identifier"><?= e(member_identifier($person)) ?></strong><?php if(trim((string)$person['official_membership_id'])===''): ?><p class="small text-secondary">Party ID has not been recorded. The system number is retained.</p><?php else: ?><small class="text-secondary">Sys No.: <?= e($person['member_number']) ?></small><?php endif; ?><hr><span class="small text-secondary">Joined membership</span><strong><?= e(date_display($person['joined_on'])) ?></strong><?php else: ?><p class="small text-secondary mb-0">This is a voter record. A nomination does not create membership until approved.</p><?php endif; ?></section><section class="card card-body mt-4"><h2 class="h6">Your access</h2><p class="small text-secondary mb-0"><?= $contacts?'Contact details are visible for this person under your current office permissions.':'Contact details and date of birth are restricted for this person.' ?></p><?php if($member): ?><p class="small text-secondary mt-2 mb-0">Membership and personal changes go through the member workflow. Use Flag a correction if you need a change reviewed.</p><?php endif; ?></section></aside>
<div><nav class="ep-sections no-print" aria-label="Profile sections"><a href="#ep-personal">Personal</a><a href="#ep-electoral">Electoral</a><a href="#ep-residential">Residence</a><?php if($member&&$background): ?><a href="#ep-background">Background</a><?php endif; ?><?php if($canNominate||$canApprove): ?><a href="#ep-membership">Membership nomination</a><?php endif; ?><?php if($review): ?><a href="#ep-review">Flag a correction</a><?php endif; ?></nav>
<section class="card card-body" id="ep-personal"><h2 class="h5">Personal details</h2><dl class="ep-details"><?php foreach(['first_name'=>'First name','last_name'=>'Last name','gender'=>'Gender','voter_id'=>'Voter ID'] as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($key==='gender'?label($person[$key]):$display($person[$key])) ?></dd></div><?php endforeach; ?><?php if($contacts): ?><div><dt>Date of birth</dt><dd><?= e($person['date_of_birth']?date_display($person['date_of_birth']):'Not recorded') ?></dd></div><?php endif; ?></dl></section>
<section class="card card-body mt-4" id="ep-electoral"><h2 class="h5">Electoral location</h2><dl class="ep-details"><?php foreach(['region'=>'Region','constituency'=>'Constituency','branch'=>'Electoral area / branch','station'=>'Polling station','station_code'=>'Station ID'] as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($key==='branch'?($person[$key]?:'Branch not assigned'):$display($person[$key])) ?></dd></div><?php endforeach; ?></dl><p class="ep-note">Branch derives from the polling station. Residential location does not change electoral assignment.</p></section>
<section class="card card-body mt-4" id="ep-residential"><h2 class="h5">Residence and contact</h2><dl class="ep-details"><?php foreach(['town'=>'Town','residential_district'=>'Residential district','residential_region'=>'Residential region'] as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($display($person[$key])) ?></dd></div><?php endforeach; ?><?php if($contacts): ?><?php foreach(['phone'=>'Phone','email'=>'Email','address'=>'Street address'] as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($display(\App\Crypto::decrypt($person[$key.'_encrypted']))) ?></dd></div><?php endforeach; ?><?php endif; ?></dl><?php if(!$contacts): ?><p class="ep-note"><i class="bi bi-lock me-1" aria-hidden="true"></i>Phone, email and street address are hidden by your permissions.</p><?php endif; ?></section>
<?php if($member&&$background): ?><section class="card card-body mt-4" id="ep-background"><h2 class="h5">Member background</h2><dl class="ep-details"><?php foreach(['profession'=>'Profession','education_level'=>'Education','employment_status'=>'Employment','job_title'=>'Job title','employer'=>'Employer','skills'=>'Skills','languages'=>'Languages','volunteer_interests'=>'Volunteer interests','availability'=>'Availability'] as $key=>$label): $value=$background[$key];if($value===null||$value===''){continue;}$value=\App\MemberProfileService::choices()[$key][$value]??$value; ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl></section><?php endif; ?>
<?php if(!$member&&($canNominate||$canApprove)): ?><section class="card card-body mt-4 no-print" id="ep-membership"><h2 class="h5">Membership nomination</h2><?php if($nomination): ?><span class="badge bg-warning text-dark align-self-start mb-3">Pending approval</span><p class="small text-secondary">A nomination already exists for this voter. Membership has not yet been created.</p><?php if($canApprove||(int)$nomination['nominated_by_user_id']===(int)\App\Auth::user()['id']): ?><a class="btn btn-outline-primary align-self-start" href="<?= e(url('membership_nomination',['id'=>$nomination['id']])) ?>"><?= $canApprove?'Review nomination':'View my nomination' ?></a><?php endif; ?><?php elseif($canNominate): ?><p class="small text-secondary">Submit this voter for membership approval by an administrator or an authorized constituency reviewer.</p><form method="post" action="<?= e(url()) ?>"><?= csrf() ?><input type="hidden" name="_action" value="membership_nominate"><input type="hidden" name="voter_id" value="<?= (int)$person['id'] ?>"><input type="hidden" name="voter_version" value="<?= e($person['updated_at']) ?>"><label for="ep-nomination-note" class="form-label">Reviewer note (optional)</label><textarea id="ep-nomination-note" class="form-control mb-3" name="note" rows="3" maxlength="1000"></textarea><label class="d-block mb-3"><input type="checkbox" required> I have reviewed the voter and intend to submit this nomination.</label><button class="btn btn-primary">Nominate as a potential member</button></form><?php else: ?><p class="small text-secondary mb-0">No pending nomination is recorded for this voter. Constituency approval starts after a nomination is submitted.</p><?php endif; ?></section><?php endif; ?>
<?php if($review): ?><section class="card card-body mt-4 no-print" id="ep-review"><h2 class="h5">Flag a correction</h2><p class="small text-secondary">Send an issue to an administrator or registrar. This does not directly change the record. Avoid unnecessary personal information.</p><form method="post" action="<?= e(url()) ?>"><?= csrf() ?><input type="hidden" name="_action" value="executive_flag"><input type="hidden" name="voter_id" value="<?= (int)$person['id'] ?>"><label class="form-label" for="ep-review-note">Issue to review</label><textarea class="form-control mb-3" id="ep-review-note" name="note" maxlength="1000" rows="3" required></textarea><button class="btn btn-outline-primary">Send for review</button></form></section><?php endif; ?></div></div></div>
